const {Client}=require("@modelcontextprotocol/sdk/client/index.js");
const {StdioClientTransport}=require("@modelcontextprotocol/sdk/client/stdio.js");
const fs=require("fs");
const S="/tmp/cairn-schema-probe.mjs";
fs.writeFileSync(S,`let b="";process.stdin.on("data",d=>{b+=d;let n;while((n=b.indexOf("\\n"))!==-1){const l=b.slice(0,n).trim();b=b.slice(n+1);if(!l)continue;const m=JSON.parse(l);const s=r=>process.stdout.write(JSON.stringify({jsonrpc:"2.0",id:m.id,result:r})+"\\n");if(m.method==="initialize")s({protocolVersion:"2025-06-18",capabilities:{tools:{}},serverInfo:{name:"p",version:"1"}});else if(m.method==="tools/list")s({tools:[{name:"t",inputSchema:{type:"object"},outputSchema:{type:"object",properties:{c:{type:"number"}},required:["c"]}}]});else if(m.method==="tools/call")s({content:[{type:"text",text:"two"}]});else if(m.id!==undefined)s({});}});`);
(async()=>{
  const out=[];
  for (const listFirst of [false,true]) {
    const c=new Client({name:"probe",version:"0"},{capabilities:{}});
    await c.connect(new StdioClientTransport({command:"node",args:[S]}));
    if(listFirst) await c.listTools();
    try { await c.callTool({name:"t",arguments:{}}); out.push("accepted"); }
    catch(e){ out.push("threw"); }
    await c.close();
  }
  console.log("without listTools:"+out[0]+"  after listTools:"+out[1]);
  process.exit(out[0]==="accepted" && out[1]==="threw" ? 0 : 1);
})();
